#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

const int MAX_SIZE=33;
const long long MOD=1000000007;

struct Matrix {
    long long data[MAX_SIZE][MAX_SIZE];
};

Matrix multiply(const Matrix &m1, const Matrix &m2, int size) {
    Matrix res = {};
    for (int i=0; i<=size; ++i)
        for (int j=0; j<=size; ++j) {
            long long sum=0;
            for (int p=0; p<=size; ++p)
                sum=(sum + m1.data[i][p]*m2.data[p][j])%MOD;
            res.data[i][j]=sum;
        }
    return res;
}

int main() {
    long long n;
    int k;
    cin >> n >> k;

    Matrix result = {};
    for (int i=0; i<=k; ++i)
        result.data[i][i]=1;

    vector<Matrix> transition(k);
    for (int p=0; p<k; ++p) {
        for (int i=0; i<=k; ++i)
            for (int j=0; j<=k; ++j)
                transition[p].data[i][j]= (i==j || i==p) ? 1 : 0;
    }

    vector<int> digits;
    for (long long temp=n; temp>0; temp/=k)
        digits.push_back(temp%k);
    digits.push_back(0);
    partial_sum(digits.rbegin(), digits.rend(), digits.rbegin());

    for (size_t p=0; p+1<digits.size(); ++p) {
        for (int i=digits[p]-1; i>=digits[p+1]; --i)
            result=multiply(result, transition[i%k], k);
        vector<Matrix> pre(k), suf(k);
        pre[0]=transition[0];
        for (int i=1; i<k; ++i)
            pre[i]=multiply(pre[i-1], transition[i], k);
        suf[k-1]=transition[k-1];
        for (int i=k-2; i>=0; --i)
            suf[i]=multiply(transition[i], suf[i+1], k);
        result=multiply(result, suf[0], k);
        for (int i=1; i<k; ++i)
            result=multiply(suf[i], pre[i-1], k);
    }

    long long total=0;
    for (int i=0; i<=k; ++i)
        total+=result.data[i][k];
    cout << total%MOD << endl;
    return 0;
}
